export type SummaryRollupGenerationOptions = {
  /** 生成请求唯一标识符，可通过 stopGenerationById 停止本次请求 */
  generation_id?: string;
  /** 返回 true 表示任务已被外部取消，不再请求或重试 */
  should_cancel?: () => boolean;
};

function buildSummaryRollupUserContent(summaries: SummaryContextEntry[]): string {
  return [
    '[待整合的分段剧情摘要，按时间顺序排列]',
    ...summaries.map(summary => `#${summary.message_id}\n${summary.summary}`),
    '[待整合的分段剧情摘要结束]',
    '请跨楼层归并同一事件、删除重复和琐碎描述，按剧情阶段重新组织成篇幅约为素材一半的前情；不要逐条拼接。保留关键事实、转折、未决事项和本分段末尾状态，只返回包含 article 的 JSON 对象。',
  ].join('\n\n');
}

function buildSummaryRollupSchema(): JsonSchema {
  return {
    name: 'cosmos_memory_summary_rollup',
    description: '由多条剧情摘要整合而成的连贯前情提要文章',
    strict: true,
    value: {
      type: 'object',
      properties: {
        article: {
          type: 'string',
          description:
            '跨楼层归并事件并去重后的精炼前情文章，按时间顺序保留关键事实、转折、未决事项和最终状态；不得逐条拼接摘要',
        },
      },
      required: ['article'],
      additionalProperties: false,
    },
  };
}

function parseSummaryRollupJson(raw: string): string {
  return parsePrettified(SummaryRollupResponse, parseAiJson(raw)).article;
}

async function rollupSummariesWithStructuredOutput(
  settings: AiSettings,
  summaries: SummaryContextEntry[],
  options: SummaryRollupGenerationOptions,
): Promise<string> {
  const result = await generateRawWithSettings(settings, {
    should_silence: true,
    generation_id: options.generation_id,
    ordered_prompts: [
      { role: 'system', content: SUMMARY_ROLLUP_SYSTEM_PROMPT },
      { role: 'user', content: `请整合以下剧情摘要：\n\n${buildSummaryRollupUserContent(summaries)}` },
    ],
    json_schema: buildSummaryRollupSchema(),
  });

  if (typeof result !== 'string') {
    throw new Error(t`二次总结请求返回了非文本结果。`);
  }

  return parseSummaryRollupJson(result);
}

async function rollupSummariesWithJsonPrompt(
  settings: AiSettings,
  summaries: SummaryContextEntry[],
  options: SummaryRollupGenerationOptions,
): Promise<string> {
  const result = await generateRawWithSettings(settings, {
    should_silence: true,
    generation_id: options.generation_id,
    ordered_prompts: [
      { role: 'system', content: SUMMARY_ROLLUP_SYSTEM_PROMPT },
      {
        role: 'user',
        content: `${SUMMARY_ROLLUP_JSON_INSTRUCTION}\n\n${buildSummaryRollupUserContent(summaries)}`,
      },
    ],
  });

  if (typeof result !== 'string') {
    throw new Error(t`二次总结请求返回了非文本结果。`);
  }

  return parseSummaryRollupJson(result);
}

/** 把一个固定分段内的多条剧情摘要二次总结为一篇连贯文章 */
export async function rollupSummariesToArticle(
  settings: AiSettings,
  summaries: SummaryContextEntry[],
  options: SummaryRollupGenerationOptions = {},
): Promise<string> {
  buildCustomApi(settings);
  return retryAiRequest(
    settings,
    retry_index =>
      retry_index === 0
        ? rollupSummariesWithStructuredOutput(settings, summaries, options)
        : rollupSummariesWithJsonPrompt(settings, summaries, options),
    options.should_cancel,
  );
}
