const SUMMARY_STORAGE_PATH = `${STORAGE_ROOT}.summaries`;
/**
 * swipe 分支摘要旁路缓存：`{root}.summary_swipes.{message_id}.{swipe_id} = MessageSummary`。
 * 与 canonical（SUMMARY_STORAGE_PATH，仅存当前激活分支）并存，切回已总结过的分支时直接复用缓存、不再调用 AI。
 */
const SUMMARY_SWIPE_STORAGE_PATH = `${STORAGE_ROOT}.summary_swipes`;
const SUMMARY_BACKFILL_CONCURRENCY = 2;
/** 摘要保存或删除后通知展示层刷新，覆盖自动总结与手动补全等入口。 */
export const message_summaries_revision = ref(0);
/**
 * 开场白所在楼层：first_message 事件始终以楼层 0 触发。
 * 未开启「包括开场白」时，开场白始终保留在上下文中且不参与总结；开启后则参与总结与压缩隐藏。
 */
export const OPENING_MESSAGE_ID = 0;

type SummarizingTask = {
  promise: Promise<MessageSummary | null>;
  generation_id: string;
};

const summarizing_messages = new Map<number, SummarizingTask>();
type MessageSummaryStatus = {
  chat_id: string | null;
  swipe_id: number;
  content: string;
} & ({ state: 'summarizing' } | { state: 'failed'; error: string });

// 请求状态只在内存中保留，不作为剧情数据保存。
const message_summary_statuses = new Map<number, MessageSummaryStatus>();

export function getMessageSummaryStatus(message_id: number): MessageSummaryStatus | undefined {
  const status = message_summary_statuses.get(message_id);
  if (!status || status.chat_id !== safeGetCurrentChatId() || status.swipe_id !== getActiveSwipeId(message_id)) {
    return undefined;
  }
  const message = window.TavernHelper.getChatMessages(message_id, { include_swipes: false })[0];
  // 进行中的请求使用启动时的正文快照；编辑是否重启请求由编辑事件和设置决定。
  // 失败状态仍只属于原正文，避免编辑后显示旧内容的错误。
  return message && (status.state === 'summarizing' || message.message === status.content) ? status : undefined;
}

const cancelled_message_ids = new Set<number>();
let backfill_abort_signal: { aborted: boolean } | null = null;

export type MessageSummary = {
  message_id: number;
  /** 生成该摘要时激活的 swipe 分支序号；用于检测切换分支后摘要是否已过期 */
  swipe_id?: number;
  /** 生成该摘要时所依据的 AI 原文（正则过滤后）内容哈希；swipe 删除/重排后按内容校验缓存是否仍有效 */
  content_hash?: number;
  summary: string;
  character_operations?: CharacterOperation[];
  item_operations?: ItemOperation[];
  location_operations?: LocationOperation[];
  setting_change_operations?: SettingChangeOperation[];
  current_info_update?: CurrentInfoUpdate | null;
  current_scene?: string | null;
  updated_at: string;
};

export type MemoryBacktrackCheckOptions = {
  max_message_id?: number;
};

export type MemoryBacktrackCheckResult = {
  max_message_id: number;
  removed_summaries: MessageSummary[];
  summarized_summaries: MessageSummary[];
  rebuilt: boolean;
  aborted: boolean;
};

export function getAssistantMessage(message_id: number): ChatMessage | null {
  const message = window.TavernHelper.getChatMessages(message_id, { include_swipes: false })[0];
  if (!message) {
    console.info('[CosmosMemory] 未找到消息楼层', { message_id });
    return null;
  }

  if (message.role !== 'assistant') {
    console.info('[CosmosMemory] 跳过非 assistant 消息', { message_id, role: message.role });
    return null;
  }

  console.info('[CosmosMemory] 获取到 assistant 消息', {
    message_id,
    content_length: message.message.length,
    is_hidden: message.is_hidden,
  });
  return message;
}

/**
 * 读取指定楼层当前激活的 swipe 分支序号。
 * 未产生过 swipe 的楼层其 swipe_id 可能为 undefined，此时归一化为 0。
 */
export function getActiveSwipeId(message_id: number): number {
  try {
    const message = window.TavernHelper.getChatMessages(message_id, { include_swipes: true })[0] as
      ChatMessageSwiped | undefined;
    if (message && typeof message.swipe_id === 'number') {
      return message.swipe_id;
    }
  } catch (error) {
    console.warn('[CosmosMemory] 读取楼层 swipe_id 失败', { message_id, error });
  }
  return 0;
}

/**
 * 对消息文本完整应用酒馆正则过滤：
 * 1. 优先应用 display（仅格式显示）：酒馆新建正则默认勾选此项，绝大多数用户/预设正则（如过滤 <think> 思考标签、UI 提示等）仅在 display 生效；
 * 2. 随后应用 prompt（仅格式提示词）：保证提示词专用的正则过滤也能生效；
 * 3. 传入角色名作为 characterOverride，确保角色专属局部正则正常生效；
 * 4. 不传 depth（为 undefined），不对深度做限制，避免历史楼层因 depth 限制而被误跳过正则。
 */
export function getRegexedContent(
  text: string,
  source: 'ai_output' | 'user_input' = 'ai_output',
  character_name?: string,
): string {
  if (!text || typeof text !== 'string') {
    return '';
  }

  if (!window.TavernHelper?.formatAsTavernRegexedString) {
    return text.trim();
  }

  try {
    let result = text;
    // 1. 先应用 display（仅格式显示）
    result = window.TavernHelper.formatAsTavernRegexedString(result, source, 'display', {
      character_name,
    });
    // 2. 再应用 prompt（仅格式提示词）
    result = window.TavernHelper.formatAsTavernRegexedString(result, source, 'prompt', {
      character_name,
    });
    return result.trim();
  } catch (error) {
    console.warn('[CosmosMemory] 应用酒馆正则过滤失败，回退到原始文本', error);
    return text.trim();
  }
}

export function getRegexedAiContent(message: ChatMessage): string {
  const { summary } = useSettingsStore().settings;
  // 在酒馆显示正则移除标签之前提取正文，避免标签被剥离后无法匹配。
  const body = filterBodyContent(message.message, summary?.filter_body ?? false, summary?.body_tag ?? '');
  const regexed_content = getRegexedContent(body, 'ai_output', message.name);

  console.info('[CosmosMemory] 完成酒馆正则过滤', {
    message_id: message.message_id,
    original_length: message.message.length,
    regexed_length: regexed_content.length,
  });

  return regexed_content;
}

export function getRegexedMessageContent(message: ChatMessage): string {
  if (message.role === 'user') {
    return getRegexedContent(message.message, 'user_input', message.name);
  }
  return getRegexedAiContent(message);
}

function getPreviousAssistantOriginalMessages(
  message_id: number,
  include_opening_message: boolean,
): OriginalMessageContextEntry[] {
  if (message_id <= OPENING_MESSAGE_ID) {
    return [];
  }

  const assistant_messages = window.TavernHelper.getChatMessages(`0-${message_id - 1}`, {
    role: 'assistant',
    include_swipes: false,
  });
  const opening_message = include_opening_message
    ? assistant_messages.find(message => message.message_id === OPENING_MESSAGE_ID)
    : undefined;
  const previous_assistant_message = assistant_messages
    .filter(message => message.message_id > OPENING_MESSAGE_ID)
    .at(-1);

  return [opening_message, previous_assistant_message]
    .filter((message): message is ChatMessage => message !== undefined)
    .map(message => {
      const content = getRegexedAiContent(message);

      if (!content) {
        console.info('[CosmosMemory] AI 原文正则过滤后的内容为空，跳过发送', {
          message_id: message.message_id,
        });
        return undefined;
      }

      return {
        message_id: message.message_id,
        name: message.name,
        role: message.role,
        content,
      };
    })
    .filter((message): message is OriginalMessageContextEntry => message !== undefined);
}

function getPreviousSummaryContext(
  message_id: number,
  count: number,
  excluded_message_ids: ReadonlySet<number> = new Set(),
): SummaryContextEntry[] {
  if (count <= 0) {
    return [];
  }

  return getStoredMessageSummaries()
    .filter(summary => summary.message_id < message_id && !excluded_message_ids.has(summary.message_id))
    .slice(-count)
    .map(summary => ({
      message_id: summary.message_id,
      summary: summary.summary,
    }));
}

function saveMessageSummary(summary: MessageSummary) {
  const swipe_id = summary.swipe_id ?? 0;
  window.TavernHelper.updateVariablesWith(
    variables => {
      // canonical：当前激活分支的摘要，供全部下游消费者读取（每层一条）
      _.set(variables, `${SUMMARY_STORAGE_PATH}.${summary.message_id}`, summary);
      // 旁路缓存：按分支保留，切回该分支时可直接复用
      _.set(variables, `${SUMMARY_SWIPE_STORAGE_PATH}.${summary.message_id}.${swipe_id}`, summary);
      return variables;
    },
    { type: 'chat' },
  );
  message_summaries_revision.value++;
  console.info('[CosmosMemory] 已写入聊天变量', {
    path: `${SUMMARY_STORAGE_PATH}.${summary.message_id}`,
    message_id: summary.message_id,
    swipe_id,
  });
}

/**
 * 读取指定楼层某个 swipe 分支已缓存的摘要（若存在）。
 * 仅做基础结构校验，字段完整性交由 getStoredMessageSummaries 的归一化路径复用处理。
 */
function getCachedSwipeSummary(message_id: number, swipe_id: number): MessageSummary | null {
  const variables = window.TavernHelper.getVariables({ type: 'chat' });
  const cached = _.get(variables, `${SUMMARY_SWIPE_STORAGE_PATH}.${message_id}.${swipe_id}`) as
    MessageSummary | undefined;
  if (
    cached &&
    typeof cached === 'object' &&
    typeof cached.message_id === 'number' &&
    typeof cached.summary === 'string'
  ) {
    return cached;
  }
  return null;
}

/** 删除指定楼层整棵 swipe 分支缓存子树（楼层被删除或被判无效时清理，避免悬空）。 */
function deleteSwipeSummaryCache(message_ids: Iterable<number>) {
  const ids = [...message_ids];
  if (ids.length === 0) {
    return;
  }
  window.TavernHelper.updateVariablesWith(
    variables => {
      for (const message_id of ids) {
        _.unset(variables, `${SUMMARY_SWIPE_STORAGE_PATH}.${message_id}`);
      }
      return variables;
    },
    { type: 'chat' },
  );
}

/** 删除指定楼层某个分支的缓存项（编辑楼层后该分支内容已变，其余分支缓存保留）。 */
function deleteSwipeSummaryCacheEntry(message_id: number, swipe_id: number) {
  window.TavernHelper.updateVariablesWith(
    variables => {
      _.unset(variables, `${SUMMARY_SWIPE_STORAGE_PATH}.${message_id}.${swipe_id}`);
      return variables;
    },
    { type: 'chat' },
  );
}

/**
 * 尝试把当前激活 swipe 分支已缓存的摘要还原为 canonical。
 * 用内容哈希校验缓存与当前分支原文一致（防 swipe 删除/重排造成的 swipe_id 错位），
 * 一致则写回 canonical 并返回该摘要；无缓存或内容不符返回 null（交由调用方重新生成）。
 */
function restoreCachedSummaryForActiveSwipe(message_id: number): MessageSummary | null {
  const active_swipe_id = getActiveSwipeId(message_id);
  const cached = getCachedSwipeSummary(message_id, active_swipe_id);
  if (!cached) {
    return null;
  }

  // 缓存若带内容哈希，则校验其与当前分支原文一致；旧缓存无哈希时按 swipe_id 命中即复用
  if (typeof cached.content_hash === 'number') {
    const message = getAssistantMessage(message_id);
    const source = message ? getRegexedAiContent(message) : '';
    if (!source || getStringHash(source) !== cached.content_hash) {
      console.info('[CosmosMemory] 分支缓存内容哈希不匹配，视为未命中', { message_id, active_swipe_id });
      return null;
    }
  }

  saveMessageSummary({ ...cached, swipe_id: active_swipe_id });
  console.info('[CosmosMemory] 已从缓存还原当前 swipe 分支摘要，无需重新总结', { message_id, active_swipe_id });
  return cached;
}

function getStoredSummaryIds(): Set<number> {
  return new Set(getStoredMessageSummaries().map(summary => summary.message_id));
}

function getExistingChatMessages(max_message_id: number): ChatMessage[] {
  return window.TavernHelper.getChatMessages('0-{{lastMessageId}}', {
    include_swipes: false,
  }).filter(message => message.message_id <= max_message_id);
}

function getCurrentLastMessageId(): number {
  return window.TavernHelper.getChatMessages('0-{{lastMessageId}}', {
    include_swipes: false,
  }).reduce((max_message_id, message) => Math.max(max_message_id, message.message_id), -1);
}

async function getMissingAssistantMessageIds(max_message_id: number): Promise<number[]> {
  const stored_summary_ids = getStoredSummaryIds();
  const { settings } = useSettingsStore();
  const allow_opening = isOpeningMessageCompressionEnabled(settings);
  const candidates = getExistingChatMessages(max_message_id).filter(
    message =>
      (allow_opening || message.message_id !== OPENING_MESSAGE_ID) &&
      message.role === 'assistant' &&
      !isCosmosMemoryMessage(message) &&
      !stored_summary_ids.has(message.message_id),
  );

  const missing_ids: number[] = [];
  for (const message of candidates) {
    const source = getRegexedAiContent(message);
    const filter_result = await evaluateMessageFilter(source, settings.filter);
    if (!filter_result.filtered) {
      missing_ids.push(message.message_id);
    } else {
      console.info('[CosmosMemory] 补全检查跳过已过滤楼层', {
        message_id: message.message_id,
        reason: filter_result.reason,
      });
    }
  }

  return missing_ids;
}

export function getStoredMessageSummaries(): MessageSummary[] {
  const variables = window.TavernHelper.getVariables({ type: 'chat' });
  const summaries = _.get(variables, SUMMARY_STORAGE_PATH, {}) as Record<string, MessageSummary>;

  return Object.values(summaries)
    .filter((summary): summary is MessageSummary => {
      return (
        typeof summary === 'object' &&
        summary !== null &&
        typeof summary.message_id === 'number' &&
        typeof summary.summary === 'string'
      );
    })
    .map(summary => {
      const character_operations = CharacterOperationsResponse.safeParse(summary.character_operations);
      const item_operations = ItemOperationsResponse.safeParse(summary.item_operations);
      const location_operations = LocationOperationsResponse.safeParse(summary.location_operations);
      const setting_change_operations = SettingChangeOperationsResponse.safeParse(summary.setting_change_operations);
      const current_info_update = CurrentInfoUpdateResponse.nullable()
        .optional()
        .safeParse(summary.current_info_update);
      return {
        ...summary,
        swipe_id: typeof summary.swipe_id === 'number' ? summary.swipe_id : undefined,
        content_hash: typeof summary.content_hash === 'number' ? summary.content_hash : undefined,
        character_operations: character_operations.success ? character_operations.data : [],
        item_operations: item_operations.success ? item_operations.data : [],
        location_operations: location_operations.success ? location_operations.data : [],
        setting_change_operations: setting_change_operations.success ? setting_change_operations.data : [],
        current_info_update: current_info_update.success ? current_info_update.data : null,
        current_scene: typeof summary.current_scene === 'string' ? summary.current_scene : null,
      };
    })
    .sort((left, right) => left.message_id - right.message_id);
}

function getActiveMemorySummaries(summaries: MessageSummary[], max_message_id: number): MessageSummary[] {
  return summaries.filter(summary => {
    if (summary.message_id > max_message_id) return false;
    const message = window.TavernHelper.getChatMessages(summary.message_id, { include_swipes: true })[0];
    if (!message || (message.swipe_id ?? 0) !== (summary.swipe_id ?? 0)) return false;
    if (summary.content_hash !== undefined) {
      const current = window.TavernHelper.getChatMessages(summary.message_id, { include_swipes: false })[0];
      if (!current || getStringHash(getRegexedAiContent(current)) !== summary.content_hash) return false;
    }
    return true;
  });
}

function rebuildMemoryFromSummaries(
  summaries: MessageSummary[],
  max_message_id = window.TavernHelper.getLastMessageId(),
) {
  const active = getActiveMemorySummaries(summaries, max_message_id);
  rebuildStoredCharactersFromSummaries(active, max_message_id);
  rebuildStoredItemsFromSummaries(active, max_message_id);
  rebuildStoredLocationsFromSummaries(active, max_message_id);
  rebuildSettingChangesFromSummaries(active, max_message_id);
  rebuildStoredCurrentInfoFromSummaries(active, max_message_id);
  rebuildStoredCurrentSceneFromSummaries(active, max_message_id);
  rebuildMemoryInstructions(max_message_id);
  floor_history_revision.value++;
}

/** 没有摘要的楼层也可能有修改；聊天/分支变化时同步所有类别。 */
export function refreshMemoryForCurrentChat() {
  reconcileFloorHistories();
  rebuildMemoryFromSummaries(getStoredMessageSummaries());
}

function removeMessageSummariesMatching(shouldRemove: (summary: MessageSummary) => boolean): MessageSummary[] {
  const removed_summaries: MessageSummary[] = [];

  window.TavernHelper.updateVariablesWith(
    variables => {
      const summaries = _.get(variables, SUMMARY_STORAGE_PATH, {}) as Record<string, MessageSummary>;
      for (const [key, summary] of Object.entries(summaries)) {
        if (
          typeof summary === 'object' &&
          summary !== null &&
          typeof summary.message_id === 'number' &&
          shouldRemove(summary)
        ) {
          removed_summaries.push(summary);
          _.unset(variables, `${SUMMARY_STORAGE_PATH}.${key}`);
        }
      }

      return variables;
    },
    { type: 'chat' },
  );

  if (removed_summaries.length > 0) {
    message_summaries_revision.value++;
  }
  return removed_summaries.sort((left, right) => left.message_id - right.message_id);
}

function pruneInvalidMessageSummaries(
  max_message_id: number,
  existing_assistant_message_ids: Set<number>,
): MessageSummary[] {
  const { settings } = useSettingsStore();
  const allow_opening = isOpeningMessageCompressionEnabled(settings);
  const removed = removeMessageSummariesMatching(
    summary =>
      (!allow_opening && summary.message_id === OPENING_MESSAGE_ID) ||
      summary.message_id > max_message_id ||
      !existing_assistant_message_ids.has(summary.message_id),
  );
  // 无效楼层的分支缓存一并清理，避免悬空
  deleteSwipeSummaryCache(removed.map(summary => summary.message_id));
  return removed;
}

/**
 * 将 canonical 摘要收敛到当前激活的 swipe 分支：
 * swipe 切换只改变激活分支而不触发生成，canonical 仍是切换前分支的内容。
 * 对每个与激活分支不一致的层，优先从分支缓存还原（不调 AI）；
 * 无缓存可还原的才删除 canonical，交由后续缺失补全按当前分支生成。
 * @returns restored_count 从缓存还原的层数（canonical 已变，调用方需重建记忆）；
 *          removed 无法还原、已被删除待补全的层摘要
 */
function reconcileSummariesToActiveSwipe(max_message_id: number): {
  restored_count: number;
  removed: MessageSummary[];
} {
  const { settings } = useSettingsStore();
  const allow_opening = isOpeningMessageCompressionEnabled(settings);
  const mismatched = getStoredMessageSummaries().filter(
    summary =>
      (allow_opening || summary.message_id !== OPENING_MESSAGE_ID) &&
      summary.message_id <= max_message_id &&
      (summary.swipe_id ?? 0) !== getActiveSwipeId(summary.message_id),
  );

  if (mismatched.length === 0) {
    return { restored_count: 0, removed: [] };
  }

  const unrestorable_ids = new Set<number>();
  let restored_count = 0;
  for (const summary of mismatched) {
    if (restoreCachedSummaryForActiveSwipe(summary.message_id)) {
      restored_count += 1;
    } else {
      unrestorable_ids.add(summary.message_id);
    }
  }

  if (unrestorable_ids.size === 0) {
    return { restored_count, removed: [] };
  }

  const removed = removeMessageSummariesMatching(summary => unrestorable_ids.has(summary.message_id));
  // 被删层当前激活分支尚无缓存，删除其缓存项以免残留旧分支的错位数据
  for (const summary of removed) {
    deleteSwipeSummaryCacheEntry(summary.message_id, getActiveSwipeId(summary.message_id));
  }
  return { restored_count, removed };
}

export function pruneMessageSummariesAfterMessage(message_id: number): MessageSummary[] {
  const existing_assistant_message_ids = new Set(
    getExistingChatMessages(message_id)
      .filter(message => message.role === 'assistant')
      .map(message => message.message_id),
  );
  const removed_summaries = pruneInvalidMessageSummaries(message_id, existing_assistant_message_ids);
  const removed_edits = reconcileFloorHistories();

  if (removed_summaries.length > 0 || removed_edits) {
    console.info('[CosmosMemory] 已清理高于当前发送楼层的悬空总结', {
      current_message_id: message_id,
      removed_message_ids: removed_summaries.map(summary => summary.message_id),
    });
  }

  // 按调用方指定的楼层截断记忆，即使更高楼层尚未物理删除、或没有摘要。
  rebuildMemoryFromSummaries(getStoredMessageSummaries(), message_id);

  return removed_summaries;
}

function safeGetCurrentChatId(): string | null {
  try {
    return getCurrentChatId() || null;
  } catch (error) {
    console.warn('[CosmosMemory] 获取当前聊天 ID 失败', error);
    return null;
  }
}

async function summarizeReceivedMessageCore(
  message_id: number,
  generation_id: string,
  should_cancel: () => boolean,
): Promise<MessageSummary | null> {
  const chat_id = safeGetCurrentChatId();

  const message = getAssistantMessage(message_id);
  if (!message) {
    return null;
  }

  const source = getRegexedAiContent(message);
  if (!source) {
    console.info('[CosmosMemory] 正则过滤后的内容为空，跳过总结', { message_id });
    return null;
  }

  const { settings } = useSettingsStore();
  const filter_result = await evaluateMessageFilter(source, settings.filter);
  if (filter_result.filtered) {
    console.info('[CosmosMemory] 楼层内容被过滤规则拦截，跳过AI总结等功能', {
      message_id,
      reason: filter_result.reason,
      count: filter_result.count,
      unit: filter_result.unit,
    });
    return null;
  }

  console.info('[CosmosMemory] 开始请求 AI 总结', {
    message_id,
    use_tavern_api: settings.ai.use_tavern_api,
    custom_api_url: settings.ai.use_tavern_api ? undefined : settings.ai.custom_api_url,
    selected_model: settings.ai.use_tavern_api ? undefined : settings.ai.selected_model,
    characters_enabled: settings.characters.enabled,
    items_enabled: settings.items.enabled,
    locations_enabled: settings.locations.enabled,
    setting_changes_enabled: settings.setting_changes.enabled,
    current_info_enabled: settings.current_info.enabled,
    current_scene_enabled: settings.current_scene.enabled,
    send_descriptions_and_world_info: settings.summary.send_descriptions_and_world_info,
    send_previous_message_original: settings.summary.send_previous_message_original,
    include_opening_message_original: settings.summary.include_opening_message_original,
    send_summary_context: settings.summary.send_summary_context,
    summary_context_count: settings.summary.summary_context_count,
  });
  const previous_original_messages = settings.summary.send_previous_message_original
    ? getPreviousAssistantOriginalMessages(message_id, settings.summary.include_opening_message_original)
    : [];
  const original_message_ids = new Set(previous_original_messages.map(message => message.message_id));
  const previous_summaries = settings.summary.send_summary_context
    ? getPreviousSummaryContext(message_id, settings.summary.summary_context_count, original_message_ids)
    : [];
  // 只读取本楼层之前的时间线，不改写当前聊天快照，避免并发补全时互相污染。
  const context_message_id = message_id - 1;
  const memory_summaries = getActiveMemorySummaries(getStoredMessageSummaries(), context_message_id);
  const result = await summarizeMessage(settings.ai, source, {
    memory_instructions: getMemoryInstructions(context_message_id),
    characters_enabled: settings.characters.enabled,
    stored_characters: settings.characters.enabled ? getCharactersAtMessage(memory_summaries, context_message_id) : [],
    items_enabled: settings.items.enabled,
    stored_items: settings.items.enabled ? getItemsAtMessage(memory_summaries, context_message_id) : [],
    locations_enabled: settings.locations.enabled,
    stored_locations: settings.locations.enabled ? getLocationsAtMessage(memory_summaries, context_message_id) : [],
    setting_changes_enabled: settings.setting_changes.enabled,
    setting_changes: settings.setting_changes.enabled
      ? getSettingChangesAtMessage(memory_summaries, context_message_id)
      : [],
    current_info_enabled: settings.current_info.enabled,
    current_info: settings.current_info.enabled
      ? getCurrentInfoAtMessage(memory_summaries, context_message_id)
      : undefined,
    current_scene_enabled: settings.current_scene.enabled,
    send_descriptions_and_world_info: settings.summary.send_descriptions_and_world_info,
    world_info_scan_messages: settings.summary.send_descriptions_and_world_info
      ? [{ role: message.role, content: source }]
      : undefined,
    previous_original_messages,
    previous_summaries,
    generation_id,
    should_cancel,
  });

  // 异步请求期间任务可能被手动停止：直接丢弃结果，不再写入变量
  if (should_cancel()) {
    console.info('[CosmosMemory] 总结任务已被取消，丢弃总结结果', { message_id });
    return null;
  }

  // 异步请求期间用户可能切换了聊天：此时写入会污染新聊天的变量，直接丢弃结果
  if (safeGetCurrentChatId() !== chat_id) {
    console.warn('[CosmosMemory] 总结完成时聊天已切换，丢弃总结结果', { message_id, chat_id });
    return null;
  }

  const summary: MessageSummary = {
    message_id,
    swipe_id: getActiveSwipeId(message_id),
    content_hash: getStringHash(source),
    summary: result.summary,
    character_operations: settings.characters.enabled ? result.characters : [],
    item_operations: settings.items.enabled ? result.item_operations : [],
    location_operations: settings.locations.enabled ? result.location_operations : [],
    setting_change_operations: settings.setting_changes.enabled ? result.setting_change_operations : [],
    current_info_update: settings.current_info.enabled ? (result.current_info_update ?? null) : null,
    current_scene: settings.current_scene.enabled ? (result.current_scene ?? null) : null,
    updated_at: new Date().toISOString(),
  };

  saveMessageSummary(summary);
  // 统一按楼层重放，避免补全较早楼层或重新总结时打乱手动修改与后续剧情的顺序。
  rebuildMemoryFromSummaries(getStoredMessageSummaries());
  return summary;
}

export function summarizeReceivedMessage(message_id: number): Promise<MessageSummary | null> {
  const { settings } = useSettingsStore();
  const allow_opening = isOpeningMessageCompressionEnabled(settings);
  if (message_id === OPENING_MESSAGE_ID && !allow_opening) {
    console.info('[CosmosMemory] 开场白楼层不参与总结', { message_id });
    return Promise.resolve(null);
  }

  const existing_task = summarizing_messages.get(message_id);
  if (existing_task) {
    console.info('[CosmosMemory] 复用正在进行的楼层总结任务', { message_id });
    return existing_task.promise;
  }

  cancelled_message_ids.delete(message_id);
  const generation_id = `cosmos-memory-summary-${message_id}-${Date.now()}`;
  const status: MessageSummaryStatus = {
    chat_id: safeGetCurrentChatId(),
    swipe_id: getActiveSwipeId(message_id),
    content: window.TavernHelper.getChatMessages(message_id, { include_swipes: false })[0]?.message ?? '',
    state: 'summarizing',
  };
  const is_current_task = (): boolean => summarizing_messages.get(message_id)?.promise === promise;
  // 任务生命周期独立于展示状态：关闭「编辑后重新总结」时，正文变化不应取消请求。
  // 即使没有收到对应事件，聊天切换、分支切换或删楼也不能让旧结果落库。
  const should_cancel = (): boolean =>
    !is_current_task() ||
    safeGetCurrentChatId() !== status.chat_id ||
    getActiveSwipeId(message_id) !== status.swipe_id ||
    window.TavernHelper.getChatMessages(message_id, { include_swipes: false })[0]?.role !== 'assistant';
  const promise: Promise<MessageSummary | null> = summarizeReceivedMessageCore(message_id, generation_id, should_cancel)
    .catch(error => {
      if (!should_cancel() && message_summary_statuses.get(message_id) === status) {
        message_summary_statuses.set(message_id, {
          ...status,
          state: 'failed',
          error: error instanceof Error ? error.message : error == null ? '' : String(error),
        });
      }
      throw error;
    })
    .finally(() => {
      // 旧任务完成不能清除同楼层新请求的状态。
      if (!is_current_task()) return;
      summarizing_messages.delete(message_id);
      if (message_summary_statuses.get(message_id)?.state === 'summarizing') {
        message_summary_statuses.delete(message_id);
      }
      message_summaries_revision.value++;
    });

  summarizing_messages.set(message_id, { promise, generation_id });
  message_summary_statuses.set(message_id, status);
  message_summaries_revision.value++;
  return promise;
}

/** 停止所有进行中的总结请求，并标记中止当前的补全循环 */
export function stopSummarizeTasks() {
  if (backfill_abort_signal) {
    backfill_abort_signal.aborted = true;
  }

  for (const [message_id, task] of summarizing_messages) {
    cancelled_message_ids.add(message_id);
    try {
      window.TavernHelper.stopGenerationById(task.generation_id);
    } catch (error) {
      console.warn('[CosmosMemory] 停止总结请求失败', { message_id, error });
    }
  }
  summarizing_messages.clear();
  for (const [message_id, status] of message_summary_statuses) {
    if (status.state === 'summarizing') message_summary_statuses.delete(message_id);
  }
  message_summaries_revision.value++;
}

/** 聊天切换时调用：取消未完成的总结任务，防止结果写入新聊天 */
export function cancelSummarizationForChatChange() {
  message_summary_statuses.clear();
  message_summaries_revision.value++;
  if (summarizing_messages.size === 0 && backfill_abort_signal === null) {
    return;
  }

  console.info('[CosmosMemory] 聊天已切换，取消未完成的总结任务', { pending_count: summarizing_messages.size });
  stopSummarizeTasks();
}

export function wasSummarizeTaskCancelled(message_id: number): boolean {
  return cancelled_message_ids.has(message_id);
}

/** 取消指定楼层正在进行的总结任务（编辑楼层后，基于旧内容的任务结果必须丢弃） */
function cancelSummarizeTask(message_id: number) {
  message_summary_statuses.delete(message_id);
  message_summaries_revision.value++;
  const task = summarizing_messages.get(message_id);
  if (!task) {
    return;
  }

  cancelled_message_ids.add(message_id);
  try {
    window.TavernHelper.stopGenerationById(task.generation_id);
  } catch (error) {
    console.warn('[CosmosMemory] 停止总结请求失败', { message_id, error });
  }
  summarizing_messages.delete(message_id);
}

function deleteMessageSummary(message_id: number) {
  window.TavernHelper.updateVariablesWith(
    variables => {
      _.unset(variables, `${SUMMARY_STORAGE_PATH}.${message_id}`);
      return variables;
    },
    { type: 'chat' },
  );
  message_summaries_revision.value++;
}

/**
 * 楼层内容被编辑后调用：取消基于旧内容的进行中任务、删除旧摘要、
 * 全量重放剩余摘要（回滚旧摘要的实体变更），最后基于新内容重新总结。
 * 尚无摘要且没有进行中任务的楼层不受影响；首次总结期间编辑也会重启任务。
 * 同时失效当前激活分支的缓存项（该分支内容已变），其余分支缓存保留以便切回复用。
 */
export async function invalidateAndResummarizeMessage(message_id: number): Promise<MessageSummary | null> {
  if (!getStoredSummaryIds().has(message_id) && !summarizing_messages.has(message_id)) {
    return null;
  }

  console.info('[CosmosMemory] 楼层内容失效，回滚其变更后按当前分支重新总结', { message_id });
  cancelSummarizeTask(message_id);
  deleteMessageSummary(message_id);
  deleteSwipeSummaryCacheEntry(message_id, getActiveSwipeId(message_id));
  rebuildMemoryFromSummaries(getStoredMessageSummaries());
  return summarizeReceivedMessage(message_id);
}

/**
 * 切换到其它 swipe 分支后调用。
 * swipe 切换只改变激活分支内容而不触发生成，canonical 摘要仍是切换前分支的内容，
 * 用户「重 roll 出分支 2 又切回分支 1 继续聊」时上下文会错用分支 2 的摘要。
 * 处理逻辑（保留各分支摘要，优先复用而非重生成）：
 * 1. canonical 已对应当前分支 → 无需处理；
 * 2. 当前分支已有缓存摘要 → 直接还原为 canonical 并重建记忆，不调用 AI；
 * 3. 无缓存可复用且原本有其它分支的 canonical → 失效后按当前分支重新生成；
 * 4. 尚无任何摘要的楼层 → 不处理，交由发送前补全。
 * - 正在生成新分支的空白楼层（内容为空）不处理，交由 MESSAGE_RECEIVED 路径总结。
 */
export async function resummarizeMessageForActiveSwipe(message_id: number): Promise<MessageSummary | null> {
  const { settings } = useSettingsStore();
  const allow_opening = isOpeningMessageCompressionEnabled(settings);
  if (message_id === OPENING_MESSAGE_ID && !allow_opening) {
    return null;
  }

  const message = getAssistantMessage(message_id);
  if (!message) {
    return null;
  }

  // 空白新分支（即将生成）不处理，避免误删摘要
  const source = getRegexedAiContent(message);
  if (!source) {
    console.info('[CosmosMemory] 切换到的 swipe 分支正则过滤后为空，跳过处理', { message_id });
    return null;
  }

  const active_swipe_id = getActiveSwipeId(message_id);
  const stored = getStoredMessageSummaries().find(summary => summary.message_id === message_id);
  if (stored && (stored.swipe_id ?? 0) === active_swipe_id) {
    console.info('[CosmosMemory] canonical 摘要已对应当前 swipe 分支，无需处理', { message_id, active_swipe_id });
    return null;
  }

  // 优先从缓存复用当前分支已生成过的摘要，不重复调用 AI
  const restored = restoreCachedSummaryForActiveSwipe(message_id);
  if (restored) {
    rebuildMemoryFromSummaries(getStoredMessageSummaries());
    return restored;
  }

  // 无缓存可复用：仅当原本存在其它分支的 canonical 时才失效并重新生成；
  // 完全无摘要的楼层交由发送前补全，避免每次浏览新分支都触发生成
  if (!stored) {
    console.info('[CosmosMemory] 切换到的 swipe 楼层尚无摘要且无缓存，交由发送前补全处理', { message_id });
    return null;
  }

  console.info('[CosmosMemory] 当前分支无缓存摘要，失效旧分支 canonical 并按当前分支重新总结', {
    message_id,
    stored_swipe_id: stored.swipe_id ?? 0,
    active_swipe_id,
  });
  return invalidateAndResummarizeMessage(message_id);
}

/**
 * 楼层被删除后调用（重新生成会先删除旧楼层、再于同一楼层写入新内容，
 * 两者共用同一楼层号）：取消被删楼层上仍在进行的总结任务、清理这些楼层的摘要
 * 并按现存摘要全量重放（回滚其派生变更），使同楼层新消息到达时能基于新内容重新总结，
 * 与 swipe 覆盖旧摘要的处理路径保持一致。
 * @param first_deleted_message_id 删除后的剩余楼层数，即第一个被删除楼层的 id（MESSAGE_DELETED 事件参数）
 */
export function rollbackSummariesFromMessage(
  first_deleted_message_id: number,
  { purge_swipe_cache = true }: { purge_swipe_cache?: boolean } = {},
): MessageSummary[] {
  for (const message_id of message_summary_statuses.keys()) {
    if (message_id >= first_deleted_message_id) message_summary_statuses.delete(message_id);
  }
  // 被删楼层上基于旧内容的进行中任务必须取消，避免其结果写回同楼层的新消息
  for (const pending_message_id of [...summarizing_messages.keys()]) {
    if (pending_message_id >= first_deleted_message_id) {
      cancelSummarizeTask(pending_message_id);
    }
  }

  const removed_summaries = removeMessageSummariesMatching(summary => summary.message_id >= first_deleted_message_id);

  // 楼层真正被删除时（purge_swipe_cache=true）连同分支缓存一并清理；
  // 重 roll / 生成新分支的提前回滚（purge_swipe_cache=false）只回滚 canonical，
  // 保留其余分支缓存，切回旧分支时仍可复用
  if (purge_swipe_cache) {
    const cache_ids = getSwipeCacheMessageIds().filter(id => id >= first_deleted_message_id);
    deleteSwipeSummaryCache(cache_ids);
    reconcileFloorHistories(first_deleted_message_id);
  }

  if (removed_summaries.length > 0) {
    console.info('[CosmosMemory] 楼层回滚，清理对应摘要并回滚其派生变更', {
      first_deleted_message_id,
      purge_swipe_cache,
      removed_message_ids: removed_summaries.map(summary => summary.message_id),
    });
  }

  // 即使没有被删除的摘要，也必须回滚绑定在该楼层的修改。
  // 生成新分支前暂时只重放更早楼层，保留旧分支日志供切回时恢复。
  rebuildMemoryFromSummaries(
    getStoredMessageSummaries(),
    purge_swipe_cache ? window.TavernHelper.getLastMessageId() : first_deleted_message_id - 1,
  );

  return removed_summaries;
}

/** 列出分支缓存中现存的全部 message_id（用于删除时按楼层范围清理）。 */
function getSwipeCacheMessageIds(): number[] {
  const variables = window.TavernHelper.getVariables({ type: 'chat' });
  const cache = _.get(variables, SUMMARY_SWIPE_STORAGE_PATH, {}) as Record<string, unknown>;
  return Object.keys(cache)
    .map(key => Number(key))
    .filter(id => Number.isInteger(id));
}

async function backfillMissingSummaries(
  message_ids: number[],
): Promise<{ summaries: MessageSummary[]; aborted: boolean }> {
  const abort_signal = { aborted: false };
  backfill_abort_signal = abort_signal;

  toastr.info(`${t`Cosmos Memory 正在补全缺失的剧情总结，请稍候…`}（${message_ids.length}）`);

  const summaries: MessageSummary[] = [];
  let cursor = 0;
  const worker = async () => {
    while (cursor < message_ids.length && !abort_signal.aborted) {
      const message_id = message_ids[cursor];
      cursor += 1;
      console.info('[CosmosMemory] 补全楼层总结', { message_id });
      try {
        const summary = await summarizeReceivedMessage(message_id);
        if (summary) {
          summaries.push(summary);
        }
      } catch (error) {
        // 单个楼层失败（包含被手动停止）不应阻断整体补全
        console.warn('[CosmosMemory] 补全楼层总结失败，跳过该楼层', { message_id, error });
      }
    }
  };

  try {
    const worker_count = Math.min(SUMMARY_BACKFILL_CONCURRENCY, message_ids.length);
    await Promise.all(Array.from({ length: worker_count }, () => worker()));
  } finally {
    if (backfill_abort_signal === abort_signal) {
      backfill_abort_signal = null;
    }
  }

  // 并发补全时实体变更可能乱序应用，最后按楼层顺序全量重放一次保证一致性
  if (summaries.length > 0) {
    rebuildMemoryFromSummaries(getStoredMessageSummaries());
  }

  console.info('[CosmosMemory] 缺失总结补全结束', {
    requested_count: message_ids.length,
    summarized_count: summaries.length,
    aborted: abort_signal.aborted,
  });

  return { summaries, aborted: abort_signal.aborted };
}

export async function summarizeMissingAssistantMessages(): Promise<MessageSummary[]> {
  const message_ids = await getMissingAssistantMessageIds(getCurrentLastMessageId());
  if (message_ids.length === 0) {
    console.info('[CosmosMemory] 发送前检查完成，没有缺失总结的 assistant 楼层');
    return [];
  }

  console.info('[CosmosMemory] 发送前发现缺失总结的 assistant 楼层，开始补全', {
    message_ids,
    count: message_ids.length,
  });

  const { summaries } = await backfillMissingSummaries(message_ids);
  return summaries;
}

export async function runMemoryBacktrackCheck(
  options: MemoryBacktrackCheckOptions = {},
): Promise<MemoryBacktrackCheckResult> {
  const max_message_id = options.max_message_id ?? getCurrentLastMessageId();
  if (max_message_id < 0) {
    console.info('[CosmosMemory] 回溯检查完成，当前聊天没有可检查楼层');
    return {
      max_message_id,
      removed_summaries: [],
      summarized_summaries: [],
      rebuilt: false,
      aborted: false,
    };
  }

  const existing_messages = getExistingChatMessages(max_message_id);
  const existing_assistant_message_ids = new Set(
    existing_messages.filter(message => message.role === 'assistant').map(message => message.message_id),
  );

  console.info('[CosmosMemory] 开始回溯检查记忆', {
    max_message_id,
    existing_assistant_message_ids: [...existing_assistant_message_ids],
  });

  const dangling_summaries = pruneInvalidMessageSummaries(max_message_id, existing_assistant_message_ids);
  if (dangling_summaries.length > 0) {
    console.info('[CosmosMemory] 回溯检查已清理悬空总结', {
      max_message_id,
      removed_message_ids: dangling_summaries.map(summary => summary.message_id),
    });
  }

  // 将 canonical 收敛到当前激活 swipe 分支：能从缓存还原的直接复用（不调 AI），
  // 无缓存可还原的删除后交由下方缺失补全按当前分支生成
  const { restored_count: swipe_restored_count, removed: swipe_unrestorable_summaries } =
    reconcileSummariesToActiveSwipe(max_message_id);
  if (swipe_restored_count > 0 || swipe_unrestorable_summaries.length > 0) {
    console.info('[CosmosMemory] 回溯检查已按当前 swipe 分支收敛摘要', {
      max_message_id,
      restored_count: swipe_restored_count,
      unrestorable_message_ids: swipe_unrestorable_summaries.map(summary => summary.message_id),
    });
  }

  const removed_summaries = [...dangling_summaries, ...swipe_unrestorable_summaries].sort(
    (left, right) => left.message_id - right.message_id,
  );
  // 删除或从缓存还原都改变了 canonical，需重建记忆
  reconcileFloorHistories();
  const rebuilt = true;
  rebuildMemoryFromSummaries(getStoredMessageSummaries(), max_message_id);

  const missing_message_ids = await getMissingAssistantMessageIds(max_message_id);
  if (missing_message_ids.length === 0) {
    console.info('[CosmosMemory] 回溯检查完成，没有缺失总结的 assistant 楼层');
    return {
      max_message_id,
      removed_summaries,
      summarized_summaries: [],
      rebuilt,
      aborted: false,
    };
  }

  console.info('[CosmosMemory] 回溯检查发现缺失总结的 assistant 楼层，开始补全', {
    max_message_id,
    message_ids: missing_message_ids,
    count: missing_message_ids.length,
  });

  const { summaries: summarized_summaries, aborted } = await backfillMissingSummaries(missing_message_ids);

  console.info('[CosmosMemory] 回溯检查完成', {
    max_message_id,
    removed_count: removed_summaries.length,
    summarized_count: summarized_summaries.length,
    rebuilt,
    aborted,
  });

  return {
    max_message_id,
    removed_summaries,
    summarized_summaries,
    rebuilt,
    aborted,
  };
}
